update raw_items r set uses=(select count(distinct week_id) from raw_week_items i where i.item_id=r.id),
 last_used=(select max(w.week_date) from raw_week_items i join raw_weeks w on w.id=i.week_id where i.item_id=r.id)
where r.section='meat' and r.merged_into is null and exists (select 1 from raw_week_items i where i.item_id=r.id);
-- dips etc. that only appear in meat weeks belong to the meat library
update raw_items r set section='meat' where r.section<>'meat' and exists (select 1 from raw_week_items i where i.item_id=r.id and i.section='meat') and not exists (select 1 from raw_week_items i where i.item_id=r.id and i.section<>'meat');
update raw_items set nutrient='Dips' where section='meat' and merged_into is null and (name_key like '%dip%' or name_key like '%chumus%' or name_key like '%chummus%' or name_key like '%hummus%');
